steps.code:
# Extract the set of downloaded song IDs from the downloaded list
downloaded_ids = {song['song_id'] for song in downloaded}
print("Downloaded song IDs:", downloaded_ids)

# Loop: keep moving to the next song until the current song is downloaded
while True:
    result = apis.spotify.next_song(access_token=access_token)
    print("Moved to song_id:", result.get('song_id'))
    if result.get('song_id') in downloaded_ids:
        print("Found a downloaded song!")
        break

