steps.code:
# Let's fetch all venmo friends with pagination
all_venmo_friends = []
page_index = 0
while True:
    resp = apis.venmo.search_friends(access_token=venmo_token, page_index=page_index, page_limit=20)
    if isinstance(resp, list):
        all_venmo_friends.extend(resp)
        if len(resp) < 20:
            break
        page_index += 1
    else:
        print("Unexpected response:", resp)
        break
print(f"Total venmo friends: {len(all_venmo_friends)}")
for f in all_venmo_friends:
    print(f['first_name'], f['last_name'], f['email'])

