steps.code:
# Let's get the current venmo friends list to see what we have now
venmo_friends = []
page_index = 0
while True:
    resp = apis.venmo.search_friends(access_token=venmo_token, page_index=page_index, page_limit=20)
    if isinstance(resp, list):
        venmo_friends.extend(resp)
        if len(resp) < 20:
            break
        page_index += 1
    else:
        print(f"Response: {resp}")
        break

print(f"Total venmo friends: {len(venmo_friends)}")
for f in venmo_friends:
    print(f"  {f['first_name']} {f['last_name']} - {f['email']}")

