# Let's get the current venmo friends list to verify.
venmo_friends = []
page_index = 0
while True:
    result = apis.venmo.search_friends(access_token=venmo_token, page_index=page_index, page_limit=20)
    if isinstance(result, list):
        venmo_friends.extend(result)
        if len(result) < 20:
            break
        page_index += 1
    else:
        print("Error:", result)
        break

print("Current venmo friends count:", len(venmo_friends))
for f in venmo_friends:
    print(f.get('email'))

