steps.code:
# Get all songs from the library to build a mapping of title -> song_id
all_songs = []
page_index = 0
while True:
    songs_page = apis.spotify.show_song_library(access_token=spotify_login['access_token'], page_index=page_index, page_limit=20)
    if not songs_page:
        break
    all_songs.extend(songs_page)
    if len(songs_page) < 20:
        break
    page_index += 1

print(f"Found {len(all_songs)} songs in library")
# Build a mapping from (title, artist_name) to song_id
song_map = {}
for song in all_songs:
    for artist in song['artists']:
        key = (song['title'].lower(), artist['name'].lower())
        song_map[key] = song['song_id']
        # Also map just by title (in case artist doesn't match exactly)
        song_map[song['title'].lower()] = song['song_id']

print("Sample songs:")
for s in all_songs[:5]:
    print(f"  ID={s['song_id']}, Title={s['title']}, Artists={[a['name'] for a in s['artists']]}")

