steps.code:
# Verify the removal and addition by checking each playlist's current songs.
# We'll fetch each playlist's details and check for archived song IDs.

archived_song_ids = {song_id for song_id, _, _ in song_ids_to_archive}
print("Archived song IDs:", archived_song_ids)

# Check all playlists except 654 for any remaining archived songs
for playlist in playlists:
    pid = playlist["playlist_id"]
    if pid == 654:
        continue
    pl = apis.spotify.show_playlist(playlist_id=pid, access_token=login_result["access_token"])
    current_song_ids = {song["id"] for song in pl["songs"]}
    remaining = current_song_ids & archived_song_ids
    if remaining:
        print(f"WARNING: Playlist {pid} ({pl['title']}) still contains archived songs: {remaining}")
    else:
        print(f"OK: Playlist {pid} ({pl['title']}) has no archived songs.")

# Check the "Old Songs" playlist (654) contains all archived songs
old_pl = apis.spotify.show_playlist(playlist_id=654, access_token=login_result["access_token"])
old_song_ids = {song["id"] for song in old_pl["songs"]}
missing = archived_song_ids - old_song_ids
if missing:
    print(f"WARNING: Old Songs playlist is missing archived songs: {missing}")
else:
    print(f"OK: Old Songs playlist contains all {len(archived_song_ids)} archived songs.")

