# Let's fetch details for all unique song IDs to match against songs_to_archive.
song_details = {}
for song_id in all_song_ids:
    song = apis.spotify.show_song(song_id=song_id)
    song_details[song_id] = song
print("Fetched", len(song_details), "songs")
# Print a few to see structure
for sid, s in list(song_details.items())[:3]:
    print(sid, s['title'], [a['name'] for a in s['artists']])

