# Verify all target songs are removed from all playlists and added to the new playlist
target_song_ids = {295, 324, 22, 245, 320, 92, 299, 4, 278, 69, 219, 298, 265}
playlist_ids = [513, 514, 515, 516, 517, 518, 519]
new_playlist_id = 654

# Check each playlist for any remaining target songs
for pid in playlist_ids:
    playlist_info = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    if 'songs' in playlist_info:
        song_ids = {song['id'] for song in playlist_info['songs']}
        remaining = song_ids & target_song_ids
        if remaining:
            print(f"Playlist {pid} still has target songs: {remaining}")
        else:
            print(f"Playlist {pid} clean")
    else:
        print(f"Error getting playlist {pid}: {playlist_info}")

# Check new playlist for all target songs
new_playlist = apis.spotify.show_playlist(playlist_id=new_playlist_id, access_token=spotify_token)
if 'songs' in new_playlist:
    new_song_ids = {song['id'] for song in new_playlist['songs']}
    missing = target_song_ids - new_song_ids
    if missing:
        print(f"New playlist missing target songs: {missing}")
    else:
        print("All target songs are in new playlist")
else:
    print(f"Error getting new playlist: {new_playlist}")

