steps.code:
# Let's parse the note content to identify songs that need release month info
content = note['content']
lines = content.split('\n')
songs_to_fix = []
for line in lines:
    line = line.strip()
    if line.startswith('- '):
        # Extract song title and artists
        # Format: - Song Title BY Artist1, Artist2 RELEASED_AT TODO
        # We'll split on " BY " and then on " RELEASED_AT "
        if ' RELEASED_AT ' in line:
            song_part, released_part = line.split(' RELEASED_AT ', 1)
            if released_part == 'TODO':
                # Extract title and artists
                if ' BY ' in song_part:
                    title_part, artists_part = song_part.split(' BY ', 1)
                    title = title_part.strip()
                    artists = [a.strip() for a in artists_part.split(',')]
                    songs_to_fix.append({'title': title, 'artists': artists, 'line': line})
                else:
                    print("No BY found in:", line)
            else:
                # Already has release month, skip
                pass
        else:
            print("No RELEASED_AT in:", line)

print("Songs to fix:", len(songs_to_fix))
for s in songs_to_fix:
    print(s['title'], "by", s['artists'])

