        # Format: - Song Title BY Artist1, Artist2 RELEASED_AT ...
        # Split on " BY " and " RELEASED_AT "
        if ' BY ' in line and ' RELEASED_AT ' in line:
            title_part = line.split(' BY ')[0][2:]  # remove "- "
            rest = line.split(' BY ')[1]
            artists_part = rest.split(' RELEASED_AT ')[0]
            release_part = rest.split(' RELEASED_AT ')[1]
            if release_part.strip() == 'TODO':
                songs_todo.append({
                    'title': title_part.strip(),
                    'artists': [a.strip() for a in artists_part.split(',')],
                    'line': line
                })
print(f"Number of songs with TODO: {len(songs_todo)}")
for s in songs_todo:
    print(s)

